## 1. 标准化JSON输出Schema

> 本章来源：附录I - 标准化JSON输出Schema

### 1.1 通用响应包装

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "required": ["version", "timestamp", "layer", "status", "data"],
  "properties": {
    "version": {
      "type": "string",
      "description": "协议版本",
      "example": "1.0"
    },
    "timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "输出时间?
    },
    "layer": {
      "type": "string",
      "enum": ["pre_market", "alpha", "risk", "portfolio", "execution", "monitor", "attribution"],
      "description": "层级标识"
    },
    "status": {
      "type": "string",
      "enum": ["success", "warning", "error"],
      "description": "执行状?
    },
    "error": {
      "type": "object",
      "description": "错误信息（当status为error时）",
      "properties": {
        "code": {"type": "integer"},
        "message": {"type": "string"}
      }
    },
    "data": {
      "type": "object",
      "description": "业务数据负载"
    }
  }
}
```

